case class Invoice private (id: InvoiceId, lines: Vector[Line], currency: Currency) {
  def addLine(line: Line): Either[Error, Invoice] =
    if (line.currency != currency) Left(CurrencyMismatch)
    else Right(copy(lines = lines :+ line))
  def total: Money = lines.map(_.amount).sum
}

object Invoice {
  def apply(id: InvoiceId, currency: Currency): Invoice = new Invoice(id, Vector.empty, currency)
}

